'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/components/auth/auth-context';
import { createOrUpdateHealthProfile, getHealthProfile, HealthProfile } from '@/lib/api/meal-planner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ChevronLeft, ChevronRight, Save, Loader2 } from 'lucide-react';

export default function HealthProfilePage() {
  const router = useRouter();
  const { user } = useAuth();
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loadingProfile, setLoadingProfile] = useState(true);

  const [formData, setFormData] = useState<HealthProfile>({
    age: 25,
    height: 170,
    weight: 70,
    medicalConditions: [],
    allergies: [],
    dislikedFoods: [],
    activityLevel: 'Moderately Active',
    dietaryPreference: 'Non-Vegetarian',
    primaryGoal: 'Maintenance',
    mealsPerDay: 3,
    cookingSkill: 'Intermediate',
    sleepQuality: 'Good',
  });

  // Temporary state for multi-select inputs
  const [medicalConditionInput, setMedicalConditionInput] = useState('');
  const [allergyInput, setAllergyInput] = useState('');
  const [dislikedFoodInput, setDislikedFoodInput] = useState('');

  useEffect(() => {
    if (!user) {
      router.push('/auth/login');
      return;
    }

    const loadProfile = async () => {
      try {
        const response = await getHealthProfile();
        if (response.success && response.data) {
          setFormData({
            age: response.data.age,
            height: response.data.height,
            weight: response.data.weight,
            targetWeight: response.data.targetWeight,
            medicalConditions: response.data.medicalConditions || [],
            medications: response.data.medications,
            specialConditions: response.data.specialConditions || [],
            allergies: response.data.allergies || [],
            dietaryPreference: response.data.dietaryPreference as any,
            dislikedFoods: response.data.dislikedFoods || [],
            activityLevel: response.data.activityLevel as any,
            occupation: response.data.occupation,
            sleepHours: response.data.sleepHours,
            sleepQuality: response.data.sleepQuality as any,
            waterIntake: response.data.waterIntake,
            primaryGoal: response.data.primaryGoal as any,
            timeline: response.data.timeline,
            mealsPerDay: response.data.mealsPerDay,
            regionalPreference: response.data.regionalPreference,
            fastingRequirements: response.data.fastingRequirements,
            monthlyBudget: response.data.monthlyBudget,
            cookingSkill: response.data.cookingSkill as any,
            maxPrepTime: response.data.maxPrepTime,
            eatingOutFrequency: response.data.eatingOutFrequency,
            city: response.data.city,
            currentHabits: response.data.currentHabits,
          });
        }
      } catch (err: any) {
        // Profile doesn't exist yet, use defaults
        console.log('No existing profile, using defaults');
      } finally {
        setLoadingProfile(false);
      }
    };

    loadProfile();
  }, [user, router]);

  const addArrayItem = (field: keyof HealthProfile, value: string, setter: (val: string) => void) => {
    if (value.trim()) {
      const currentArray = formData[field] as string[] || [];
      setFormData({ ...formData, [field]: [...currentArray, value.trim()] });
      setter('');
    }
  };

  const removeArrayItem = (field: keyof HealthProfile, index: number) => {
    const currentArray = formData[field] as string[] || [];
    setFormData({ ...formData, [field]: currentArray.filter((_, i) => i !== index) });
  };

  const handleSubmit = async () => {
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      // Validate required fields
      if (formData.age < 1 || formData.age > 120) {
        throw new Error('Age must be between 1 and 120');
      }
      if (formData.height < 50 || formData.height > 300) {
        throw new Error('Height must be between 50 and 300 cm');
      }
      if (formData.weight < 20 || formData.weight > 300) {
        throw new Error('Weight must be between 20 and 300 kg');
      }
      if (formData.mealsPerDay < 2 || formData.mealsPerDay > 6) {
        throw new Error('Meals per day must be between 2 and 6');
      }

      const response = await createOrUpdateHealthProfile(formData);
      if (response.success) {
        setSuccess('Health profile saved successfully!');
        setTimeout(() => {
          router.push('/meal-planner');
        }, 1500);
      }
    } catch (err: any) {
      setError(err.response?.data?.message || err.message || 'Failed to save profile');
    } finally {
      setLoading(false);
    }
  };

  const nextStep = () => {
    if (currentStep < 5) setCurrentStep(currentStep + 1);
  };

  const prevStep = () => {
    if (currentStep > 1) setCurrentStep(currentStep - 1);
  };

  if (!user) return null;

  if (loadingProfile) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-blue-50 to-white flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-50 to-white py-12 px-4">
      <div className="max-w-3xl mx-auto">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">Health Profile</h1>
          <p className="text-gray-600">Tell us about yourself to get personalized meal plans</p>
        </div>

        {/* Progress Indicator */}
        <div className="mb-8">
          <div className="flex justify-between items-center">
            {[1, 2, 3, 4, 5].map((step) => (
              <div key={step} className="flex items-center">
                <div
                  className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold ${
                    step <= currentStep
                      ? 'bg-blue-600 text-white'
                      : 'bg-gray-200 text-gray-500'
                  }`}
                >
                  {step}
                </div>
                {step < 5 && (
                  <div
                    className={`w-12 md:w-24 h-1 ${
                      step < currentStep ? 'bg-blue-600' : 'bg-gray-200'
                    }`}
                  />
                )}
              </div>
            ))}
          </div>
          <div className="flex justify-between mt-2 text-xs text-gray-600">
            <span>Personal</span>
            <span>Health</span>
            <span>Dietary</span>
            <span>Lifestyle</span>
            <span>Cooking</span>
          </div>
        </div>

        {error && (
          <Alert variant="destructive" className="mb-6">
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}

        {success && (
          <Alert className="mb-6 bg-green-50 border-green-200">
            <AlertDescription className="text-green-800">{success}</AlertDescription>
          </Alert>
        )}

        <Card>
          <CardHeader>
            <CardTitle>
              {currentStep === 1 && 'Personal Information'}
              {currentStep === 2 && 'Health Status'}
              {currentStep === 3 && 'Dietary Preferences'}
              {currentStep === 4 && 'Lifestyle & Goals'}
              {currentStep === 5 && 'Cooking & Budget'}
            </CardTitle>
            <CardDescription>
              Step {currentStep} of 5
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Step 1: Personal Information */}
            {currentStep === 1 && (
              <>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="age">Age *</Label>
                    <Input
                      id="age"
                      type="number"
                      min="1"
                      max="120"
                      value={formData.age}
                      onChange={(e) => setFormData({ ...formData, age: parseInt(e.target.value) || 0 })}
                    />
                  </div>
                  <div>
                    <Label htmlFor="gender">Gender *</Label>
                    <Select
                      value={formData.gender}
                      onValueChange={(value) => setFormData({ ...formData, gender: value as any })}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="male">Male</SelectItem>
                        <SelectItem value="female">Female</SelectItem>
                        <SelectItem value="other">Other</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="height">Height (cm) *</Label>
                    <Input
                      id="height"
                      type="number"
                      min="50"
                      max="300"
                      value={formData.height}
                      onChange={(e) => setFormData({ ...formData, height: parseInt(e.target.value) || 0 })}
                    />
                  </div>
                  <div>
                    <Label htmlFor="weight">Weight (kg) *</Label>
                    <Input
                      id="weight"
                      type="number"
                      min="20"
                      max="300"
                      value={formData.weight}
                      onChange={(e) => setFormData({ ...formData, weight: parseInt(e.target.value) || 0 })}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="targetWeight">Target Weight (kg)</Label>
                  <Input
                    id="targetWeight"
                    type="number"
                    min="20"
                    max="300"
                    value={formData.targetWeight || ''}
                    onChange={(e) => setFormData({ ...formData, targetWeight: parseInt(e.target.value) || undefined })}
                    placeholder="Optional"
                  />
                </div>
              </>
            )}

            {/* Step 2: Health Status */}
            {currentStep === 2 && (
              <>
                <div>
                  <Label>Medical Conditions</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={medicalConditionInput}
                      onChange={(e) => setMedicalConditionInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('medicalConditions', medicalConditionInput, setMedicalConditionInput);
                        }
                      }}
                      placeholder="e.g., Diabetes, High blood pressure"
                    />
                    <Button
                      type="button"
                      onClick={() => addArrayItem('medicalConditions', medicalConditionInput, setMedicalConditionInput)}
                    >
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.medicalConditions?.map((condition, idx) => (
                      <span key={idx} className="bg-red-100 text-red-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {condition}
                        <button onClick={() => removeArrayItem('medicalConditions', idx)} className="hover:text-red-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>

                <div>
                  <Label>Allergies</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={allergyInput}
                      onChange={(e) => setAllergyInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('allergies', allergyInput, setAllergyInput);
                        }
                      }}
                      placeholder="e.g., Peanuts, Shellfish"
                    />
                    <Button type="button" onClick={() => addArrayItem('allergies', allergyInput, setAllergyInput)}>
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.allergies?.map((allergy, idx) => (
                      <span key={idx} className="bg-orange-100 text-orange-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {allergy}
                        <button onClick={() => removeArrayItem('allergies', idx)} className="hover:text-orange-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>

                <div>
                  <Label>Supplements Used</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={supplementInput}
                      onChange={(e) => setSupplementInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('supplementsUsed', supplementInput, setSupplementInput);
                        }
                      }}
                      placeholder="e.g., Vitamin D, Omega-3"
                    />
                    <Button type="button" onClick={() => addArrayItem('supplementsUsed', supplementInput, setSupplementInput)}>
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.supplementsUsed?.map((supplement, idx) => (
                      <span key={idx} className="bg-green-100 text-green-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {supplement}
                        <button onClick={() => removeArrayItem('supplementsUsed', idx)} className="hover:text-green-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>
              </>
            )}

            {/* Step 3: Dietary Preferences */}
            {currentStep === 3 && (
              <>
                <div>
                  <Label>Dietary Restrictions</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={dietaryRestrictionInput}
                      onChange={(e) => setDietaryRestrictionInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('dietaryRestrictions', dietaryRestrictionInput, setDietaryRestrictionInput);
                        }
                      }}
                      placeholder="e.g., Vegetarian, Vegan, Halal"
                    />
                    <Button type="button" onClick={() => addArrayItem('dietaryRestrictions', dietaryRestrictionInput, setDietaryRestrictionInput)}>
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.dietaryRestrictions?.map((restriction, idx) => (
                      <span key={idx} className="bg-purple-100 text-purple-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {restriction}
                        <button onClick={() => removeArrayItem('dietaryRestrictions', idx)} className="hover:text-purple-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>

                <div>
                  <Label>Preferred Cuisines</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={preferredCuisineInput}
                      onChange={(e) => setPreferredCuisineInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('preferredCuisines', preferredCuisineInput, setPreferredCuisineInput);
                        }
                      }}
                      placeholder="e.g., Italian, Asian, Mexican"
                    />
                    <Button type="button" onClick={() => addArrayItem('preferredCuisines', preferredCuisineInput, setPreferredCuisineInput)}>
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.preferredCuisines?.map((cuisine, idx) => (
                      <span key={idx} className="bg-blue-100 text-blue-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {cuisine}
                        <button onClick={() => removeArrayItem('preferredCuisines', idx)} className="hover:text-blue-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>

                <div>
                  <Label>Disliked Ingredients</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={dislikedIngredientInput}
                      onChange={(e) => setDislikedIngredientInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('dislikedIngredients', dislikedIngredientInput, setDislikedIngredientInput);
                        }
                      }}
                      placeholder="e.g., Cilantro, Mushrooms"
                    />
                    <Button type="button" onClick={() => addArrayItem('dislikedIngredients', dislikedIngredientInput, setDislikedIngredientInput)}>
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.dislikedIngredients?.map((ingredient, idx) => (
                      <span key={idx} className="bg-gray-100 text-gray-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {ingredient}
                        <button onClick={() => removeArrayItem('dislikedIngredients', idx)} className="hover:text-gray-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>

                <div>
                  <Label htmlFor="regionalPreference">Regional Preference</Label>
                  <Input
                    id="regionalPreference"
                    value={formData.regionalPreference || ''}
                    onChange={(e) => setFormData({ ...formData, regionalPreference: e.target.value })}
                    placeholder="e.g., Mediterranean, South Asian"
                  />
                </div>

                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="organicPreference"
                    checked={formData.organicPreference}
                    onCheckedChange={(checked) => setFormData({ ...formData, organicPreference: !!checked })}
                  />
                  <Label htmlFor="organicPreference" className="cursor-pointer">
                    Prefer organic ingredients
                  </Label>
                </div>
              </>
            )}

            {/* Step 4: Lifestyle & Goals */}
            {currentStep === 4 && (
              <>
                <div>
                  <Label htmlFor="activityLevel">Activity Level *</Label>
                  <Select
                    value={formData.activityLevel}
                    onValueChange={(value) => setFormData({ ...formData, activityLevel: value as any })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="sedentary">Sedentary (little to no exercise)</SelectItem>
                      <SelectItem value="lightly_active">Lightly Active (1-3 days/week)</SelectItem>
                      <SelectItem value="moderately_active">Moderately Active (3-5 days/week)</SelectItem>
                      <SelectItem value="very_active">Very Active (6-7 days/week)</SelectItem>
                      <SelectItem value="extremely_active">Extremely Active (athlete)</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label>Fitness Goals</Label>
                  <div className="flex gap-2 mb-2">
                    <Input
                      value={fitnessGoalInput}
                      onChange={(e) => setFitnessGoalInput(e.target.value)}
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addArrayItem('fitnessGoals', fitnessGoalInput, setFitnessGoalInput);
                        }
                      }}
                      placeholder="e.g., Weight loss, Muscle gain"
                    />
                    <Button type="button" onClick={() => addArrayItem('fitnessGoals', fitnessGoalInput, setFitnessGoalInput)}>
                      Add
                    </Button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.fitnessGoals?.map((goal, idx) => (
                      <span key={idx} className="bg-indigo-100 text-indigo-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {goal}
                        <button onClick={() => removeArrayItem('fitnessGoals', idx)} className="hover:text-indigo-600">×</button>
                      </span>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="mealsPerDay">Meals per Day *</Label>
                    <Input
                      id="mealsPerDay"
                      type="number"
                      min="2"
                      max="6"
                      value={formData.mealsPerDay}
                      onChange={(e) => setFormData({ ...formData, mealsPerDay: parseInt(e.target.value) || 3 })}
                    />
                  </div>
                  <div>
                    <Label htmlFor="snacksPerDay">Snacks per Day</Label>
                    <Input
                      id="snacksPerDay"
                      type="number"
                      min="0"
                      max="5"
                      value={formData.snacksPerDay || ''}
                      onChange={(e) => setFormData({ ...formData, snacksPerDay: parseInt(e.target.value) || undefined })}
                      placeholder="Optional"
                    />
                  </div>
                </div>
              </>
            )}

            {/* Step 5: Cooking & Budget */}
            {currentStep === 5 && (
              <>
                <div>
                  <Label htmlFor="cookingSkillLevel">Cooking Skill Level *</Label>
                  <Select
                    value={formData.cookingSkillLevel}
                    onValueChange={(value) => setFormData({ ...formData, cookingSkillLevel: value as any })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="beginner">Beginner</SelectItem>
                      <SelectItem value="intermediate">Intermediate</SelectItem>
                      <SelectItem value="advanced">Advanced</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label htmlFor="cookingTimeAvailable">Cooking Time Available *</Label>
                  <Select
                    value={formData.cookingTimeAvailable}
                    onValueChange={(value) => setFormData({ ...formData, cookingTimeAvailable: value as any })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="minimal">Minimal (15-30 min)</SelectItem>
                      <SelectItem value="moderate">Moderate (30-60 min)</SelectItem>
                      <SelectItem value="flexible">Flexible (60+ min)</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label htmlFor="budgetPerMeal">Budget per Meal ($)</Label>
                  <Input
                    id="budgetPerMeal"
                    type="number"
                    min="0"
                    step="0.01"
                    value={formData.budgetPerMeal || ''}
                    onChange={(e) => setFormData({ ...formData, budgetPerMeal: parseFloat(e.target.value) || undefined })}
                    placeholder="Optional"
                  />
                </div>
              </>
            )}

            {/* Navigation Buttons */}
            <div className="flex justify-between pt-6 border-t">
              <Button
                type="button"
                variant="outline"
                onClick={prevStep}
                disabled={currentStep === 1}
              >
                <ChevronLeft className="h-4 w-4 mr-2" />
                Previous
              </Button>

              {currentStep < 5 ? (
                <Button type="button" onClick={nextStep}>
                  Next
                  <ChevronRight className="h-4 w-4 ml-2" />
                </Button>
              ) : (
                <Button onClick={handleSubmit} disabled={loading}>
                  {loading ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="h-4 w-4 mr-2" />
                      Save Profile
                    </>
                  )}
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
